import os
from typing import Any, Dict, List, Optional

from google.cloud import vision_v1
from google.cloud.vision_v1 import AnnotateFileResponse


def extract_layout_elements(
    document_path: str,
    mime_type: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extract OCR and layout information from a document using Google Cloud Vision OCR.

    Returns a dictionary with:
      - full_text: extracted text
      - pages: page-level geometry and detected blocks/paragraphs/words/symbols
      - lines: text lines reconstructed from words/paragraphs when possible
      - blocks: detected block descriptions with bounding boxes
      - tables: table-like structures if present in OCR layout
    """
    if mime_type is None:
        ext = os.path.splitext(document_path.lower())[1]
        if ext in {".pdf"}:
            mime_type = "application/pdf"
        elif ext in {".tif", ".tiff"}:
            mime_type = "image/tiff"
        elif ext in {".png"}:
            mime_type = "image/png"
        elif ext in {".jpg", ".jpeg"}:
            mime_type = "image/jpeg"
        else:
            mime_type = "application/pdf"

    client = vision_v1.ImageAnnotatorClient()

    with open(document_path, "rb") as f:
        content = f.read()

    feature = vision_v1.Feature(type_=vision_v1.Feature.Type.DOCUMENT_TEXT_DETECTION)
    input_config = vision_v1.InputConfig(content=content, mime_type=mime_type)
    request = vision_v1.AnnotateFileRequest(
        features=[feature],
        input_config=input_config,
    )

    response = client.batch_annotate_files(requests=[request])

    return _normalize_vision_response(response)


def _normalize_vision_response(response: Any) -> Dict[str, Any]:
    result: Dict[str, Any] = {
        "full_text": "",
        "pages": [],
        "blocks": [],
        "lines": [],
        "tables": [],
    }

    for file_response in response.responses:
        for page_response in file_response.responses:
            annotation = getattr(page_response, "full_text_annotation", None)
            if annotation and annotation.text:
                result["full_text"] = annotation.text

            pages = getattr(annotation, "pages", []) if annotation else []
            for page_index, page in enumerate(pages):
                page_item = {
                    "page_number": page_index + 1,
                    "width": page.width,
                    "height": page.height,
                    "blocks": [],
                }

                for block_index, block in enumerate(page.blocks):
                    block_box = _bounding_poly_to_dict(getattr(block, "bounding_box", None) or getattr(block, "bounding_box", None))
                    block_item = {
                        "block_index": block_index,
                        "confidence": getattr(block, "confidence", None),
                        "bounding_box": block_box,
                        "paragraphs": [],
                    }

                    result["blocks"].append(
                        {
                            "page_number": page_index + 1,
                            "block_index": block_index,
                            "confidence": getattr(block, "confidence", None),
                            "bounding_box": block_box,
                        }
                    )

                    for para_index, paragraph in enumerate(block.paragraphs):
                        words = []
                        line_text = []
                        for word in paragraph.words:
                            word_text = "".join(symbol.text for symbol in word.symbols)
                            words.append(
                                {
                                    "text": word_text,
                                    "confidence": getattr(word, "confidence", None),
                                    "bounding_box": _bounding_poly_to_dict(word.bounding_box),
                                }
                            )
                            line_text.append(word_text)

                        line = " ".join(line_text).strip()
                        if line:
                            result["lines"].append(
                                {
                                    "page_number": page_index + 1,
                                    "block_index": block_index,
                                    "paragraph_index": para_index,
                                    "text": line,
                                    "confidence": getattr(paragraph, "confidence", None),
                                    "bounding_box": _bounding_poly_to_dict(paragraph.bounding_box),
                                }
                            )

                        para_item = {
                            "paragraph_index": para_index,
                            "confidence": getattr(paragraph, "confidence", None),
                            "bounding_box": _bounding_poly_to_dict(paragraph.bounding_box),
                            "words": words,
                        }
                        block_item["paragraphs"].append(para_item)

                    page_item["blocks"].append(block_item)

                result["pages"].append(page_item)

                for table in getattr(page, "blocks", []):
                    if getattr(table, "block_type", None) == vision_v1.Block.BlockType.TABLE:
                        result["tables"].append(
                            {
                                "page_number": page_index + 1,
                                "bounding_box": _bounding_poly_to_dict(table.bounding_box),
                                "confidence": getattr(table, "confidence", None),
                            }
                        )

    return result


def _bounding_poly_to_dict(poly: Any) -> Optional[Dict[str, Any]]:
    if poly is None:
        return None
    vertices = []
    for v in getattr(poly, "vertices", []) or []:
        vertices.append(
            {
                "x": getattr(v, "x", None),
                "y": getattr(v, "y", None),
            }
        )
    return {"vertices": vertices}
